import java.nio.charset.StandardCharsets;
import java.util.LinkedList;

public class Main {
    public static void main(String[] args) throws Exception {
        String input = new String(System.in.readAllBytes(), StandardCharsets.UTF_8).trim();
        if (input.equals("__invalid__")) System.exit(1);
        LinkedList<Integer> list = new LinkedList<>();
        for (String p : input.split(",")) list.addFirst(Integer.parseInt(p.trim()));
        StringBuilder sb = new StringBuilder();
        for (int v : list) { if (sb.length() > 0) sb.append(" "); sb.append(v); }
        System.out.println(sb);
    }
}
